function sectorCase(industry,id){
  if(!Object.hasOwn(sectorRecords,industry)||!sectorJobs[id])return null;
  const [area,desk,question,analysis,action]=sectorJobs[id];
  const [item,source,owner,ref,team]=sectorRecords[industry][area];
  const example=industryExamples[industry][id]||[
    item[0].toUpperCase()+item.slice(1)+' · '+question[0].toLowerCase()+question.slice(1),
    'The '+team+' is reviewing '+item+' ('+ref+'). The '+source+' has a current entry, but the latest change still needs confirmation from the '+owner+'.',
    analysis+' Use the '+source+' and identify any unconfirmed fields.',
    'The '+owner+' will '+action+'.'
  ];
  return {industry,desk,source,owner,ref,team,example};
}


