function sectorHero(industry,prefix=''){
  if(!Object.hasOwn(sectorImages,industry))return '';
  return `<div class="sector-photo"><img src="${prefix}industry-media/${sectorImages[industry]}.webp" alt=""><span>${industry.replaceAll('&','&amp;')}</span></div>`;
}
